head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > P > wheelStop]<br/>GridView 영역에서 휠버튼으로 스크롤 시 웹브라우저로 스크롤 체이닝 시킬지 설정합니다.",
    "validation" : [
        "미설정 또는 false 설정 시 GridVieiw 영역의 스크롤이 최상단 혹은 최하단에 위치한 경우 웹브라우저로 스크롤 체이닝이 됩니다.",
        "--- GridVeiw 에 세로 스크롤이 없는 경우 웹브라우저의 스크롤이 동작합니다.",
        "true 설정 시 GridView 영역의 스크롤만 동작하고 웹브라우저로 스크롤 체이닝 되지 않습니다.",
        "스크롤 체이닝(Scroll Chaining)은 GridView 의 세로 스크롤이 최상단/최하단에 위치하고 같은 방향으로 스크롤 시 동작합니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }

    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // 조건 설정
    let properties = {
        wheelStop: con_wheelStop.getText(),
        dataList: "data:dlt_bind",
    };

    let cList = $c.gcm.createCList(properties);

    // dataList 생성 (target1 내부 세로 스크롤이 생기도록 30행 생성)
    await $c.gcm.createDynamicDataList('', '', 'dlt_bind', '', 30);

    // target1 하나만 생성한 뒤 그리드 높이를 grp_comp(parentGroup) clientHeight 보다 크게(600px) 설정한다.
    //  -> grp_comp 가 오버플로하여 자체 세로 스크롤이 생기고(체이닝 대상),
    //     동시에 30행 데이터로 target1 내부 세로 스크롤도 생긴다(경계 도달 가능).
    await $c.gcm.createBasicGridView(cList);
    target1.setStyle({ height: '600px' });
}



scwin.btn_wheelScroll_onclick = function (e) {
    const targets = ["target1"];

    let resultMessage = "";
    let parentGroupElement = document.querySelector('div[id*="grp_comp"]');
    let scrollTop = "";

    targets.forEach(function(targetId) {
        let targetElement = document.querySelector('div[id*="' + targetId + '_scrollY_div"]');

        if (targetElement) {
            let scrollTop = targetElement.scrollTop;
            resultMessage += targetId + " scroll top : " + scrollTop + " / ";
        } else {
            resultMessage += targetId + " 요소 없음 / ";
        }
    });

    wf_body_bottom.getObj("scwin").setReturnValue(resultMessage);

    resultMessage = "";

     if (parentGroupElement) {
        scrollTop = parentGroupElement.scrollTop;
        resultMessage += "parentGroup scroll top : " + scrollTop + " / ";
    } else {
        resultMessage += "parentGroup 요소 없음 / ";
    }

    wf_body_bottom.getObj("scwin").setReturnValue(resultMessage);   
};
